import {find,walk,isLocked,clone} from '../document/model.js';
import {evaluated,setProperty} from '../animation/evaluate.js';
import {escape} from '../renderer/svg.js';

export function normalColour(value){if(typeof value!=='string')return null;value=value.trim().toLowerCase();if(/^#[0-9a-f]{3}$/.test(value))value='#'+[...value.slice(1)].map(c=>c+c).join('');return /^#[0-9a-f]{6}$/.test(value)?value:null;}
export function readRecentColours(storage){try{const values=JSON.parse(storage?.getItem('poppy-recent-colours')||'[]');return Array.isArray(values)?[...new Set(values.map(normalColour).filter(Boolean))].slice(0,10):[];}catch{return [];}}
export function addRecentColour(colour,storage,previous=[]){const normalized=normalColour(colour),history=[...new Set([...readRecentColours(storage),...previous.map(normalColour).filter(Boolean)])];if(!normalized)return history.slice(0,10);const colours=[normalized,...history.filter(c=>c!==normalized)].slice(0,10);try{storage?.setItem('poppy-recent-colours',JSON.stringify(colours));storage?.setItem('poppy-draw-color',normalized);}catch{}return colours;}
export function objectColourPatch(n,prop,colour,time){const v=evaluated(n,time),patch={[prop]:colour};if(prop==='fill'&&v.mesh)patch.mesh={...clone(v.mesh),points:v.mesh.points.map(p=>({...p,color:colour}))};if(prop==='stroke'&&v.strokeWidth<=0)patch.strokeWidth=2;return patch;}
export function colourTargets(a,n){const targets=[];walk([n],v=>{if(v.type!=='group'&&v.type!=='image'&&!isLocked(a.doc,v.id))targets.push(v);});return targets;}
function clearPreview(a,ids){for(const id of ids){const value=a.appearancePreview?.get(id);if(!value)continue;for(const key of ['fill','stroke','strokeWidth','mesh'])delete value[key];if(!Object.keys(value).length)a.appearancePreview.delete(id);}a.renderStage();}
export function showObjectColour(a,id=a.selected[0],property='auto'){
 const n=find(a.doc,id);if(!n||isLocked(a.doc,id))return a.toast('Select unlocked artwork to colour.');const targets=colourTargets(a,n);if(!targets.length)return a.toast('This layer has no editable fill or stroke.');a.properties.flush();a.pause();a.stage.finishPath();
 const v=evaluated(targets[0],a.time);let prop=property==='auto'?(v.fill==='none'?'stroke':'fill'):property,colour=normalColour(v[prop])||a.drawColor||'#a8adb5',dirty=false;
 let recent;try{recent=readRecentColours(globalThis.localStorage);}catch{recent=[];}if(!recent.length)recent=(a.recentColours||[]).slice(0,10);
 const d=a.dialog('Colour · '+escape(n.name),`<form><div class="colour-targets" role="group" aria-label="Colour target"><button type="button" data-colour-target="fill">Fill</button><button type="button" data-colour-target="stroke">Stroke</button></div><div class="object-colour-preview" data-colour-sample></div><label>Colour<input type="color" data-colour-native aria-label="Choose colour" value="${colour}"></label><label>Hex colour<input name="hex" aria-label="Hex colour" pattern="#[0-9a-fA-F]{6}" value="${colour}" required></label><h3>Last 10 colours</h3><div class="recent-colours">${recent.length?recent.map(c=>`<button type="button" data-recent-colour="${c}" aria-label="Use ${c}" title="${c}" style="--swatch:${c}"><span></span></button>`).join(''):'<span class="subtle">Applied colours will appear here.</span>'}</div><p class="subtle" data-colour-status></p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button type="submit" class="primary">Apply colour</button></div></form>`,(_,dialog)=>{
  const value=normalColour(dialog.querySelector('[name=hex]').value);if(!value)throw Error('Enter a six-digit hex colour.');clearPreview(a,targets.map(n=>n.id));a.mutate('Object '+prop+' colour',()=>{for(const target of targets){const current=find(a.doc,target.id);if(!current||isLocked(a.doc,current.id))continue;for(const [key,colourValue] of Object.entries(objectColourPatch(current,prop,value,a.time)))setProperty(current,key,colourValue,a.time);}a.rememberColor(value);});dialog.close();
 },{modal:false});d.classList.add('object-colour-dialog');
 const update=()=>{d.querySelector('[name=hex]').value=colour;d.querySelector('[data-colour-native]').value=colour;d.querySelector('[data-colour-sample]').style.background=colour;for(const b of d.querySelectorAll('[data-colour-target]')){b.classList.toggle('active',b.dataset.colourTarget===prop);b.setAttribute('aria-pressed',b.dataset.colourTarget===prop);}d.querySelector('[data-colour-status]').textContent=prop+' · Frame '+Math.round(a.time*a.doc.fps)+' · canvas previews until Apply';if(dirty){a.appearancePreview??=new Map();for(const target of targets){const preview={...(a.appearancePreview.get(target.id)||{}),...objectColourPatch(target,prop,colour,a.time)};a.appearancePreview.set(target.id,preview);}a.renderStage();}};
 d.querySelector('[data-colour-native]').oninput=e=>{colour=e.target.value;dirty=true;update();};d.querySelector('[name=hex]').oninput=e=>{const value=normalColour(e.target.value);if(value){colour=value;dirty=true;update();}};for(const b of d.querySelectorAll('[data-recent-colour]'))b.onclick=()=>{colour=b.dataset.recentColour;dirty=true;update();};for(const b of d.querySelectorAll('[data-colour-target]'))b.onclick=()=>{clearPreview(a,targets.map(n=>n.id));prop=b.dataset.colourTarget;colour=normalColour(evaluated(targets[0],a.time)[prop])||a.drawColor;dirty=false;update();};d.addEventListener('close',()=>clearPreview(a,targets.map(n=>n.id)),{once:true});update();return d;
}
